SELECT s.* FROM report_submissions s INNER JOIN ( SELECT assignment_id, MAX(version) AS max_version FROM report_submissions WHERE assignment_id IN
#{assignmentId}
GROUP BY assignment_id ) latest ON s.assignment_id = latest.assignment_id AND s.version = latest.max_version

SELECT s.* FROM report_submissions s INNER JOIN ( SELECT assignment_id, MAX(version) AS max_version FROM report_submissions WHERE assignment_id IN
#{assignmentId}
AND status NOT IN ('draft', 'rejected', 'returned') GROUP BY assignment_id ) latest ON s.assignment_id = latest.assignment_id AND s.version = latest.max_version
